{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Telbivudine, a thymidine nucleoside analogue closely matching the query's 5-methyluracil core and sugar-like ring, has an absolute oral bioavailability of ~52% in subjects with normal renal function, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Zidovudine, a 3'-modified thymidine analogue, is well absorbed orally with a reported bioavailability of 65% in children, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Zidovudine absolute oral bioavailability was 64% ± 21.3% in HIV-infected patients after a 200 mg oral dose versus intravenous administration, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sorivudine, a 5-substituted uracil nucleoside analogue, has an absolute oral bioavailability of approximately 60%, supporting high F for this pyrimidine nucleoside class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Doxifluridine, a deoxyfluorouridine nucleoside analogue, shows oral bioavailability of 34–47% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "D07001-F4, a fluorinated pyrimidine nucleoside analogue, has a mean oral bioavailability of approximately 39% in patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence from closely related pyrimidine nucleoside analogues reports absolute oral bioavailability above 20%, mostly in the 39–80% range. The query's favorable physicochemical profile and structural similarity to these analogues support a high oral bioavailability prediction (F >= 20%).",
  "evidence_gaps": [
    "No direct stavudine absolute bioavailability measurement is present in the evidence set; all values come from analogues with moderate Morgan similarity.",
    "Some analogues (e.g., 882C87, OGT719) have bioavailability near the 20% threshold, adding minor uncertainty about the exact magnitude.",
    "No direct data on intestinal transporters, efflux, or first-pass metabolism specific to the query are provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

